use parth_db::exec::execute; use parth_db::Database; fn count(db: &Database, sql: &str) -> usize { execute(db, sql).unwrap().rows.len() } #[test] fn between_and_in_filter_rows() { let dir = std::env::temp_dir().join(format!("parth_in_between_{}", std::process::id())); let _ = std::fs::remove_dir_all(&dir); let db = Database::open(&dir).unwrap(); execute(&db, "CREATE TABLE t (id INT PRIMARY KEY, v INT)").unwrap(); execute(&db, "INSERT INTO t VALUES (1, 10), (2, 20), (3, 30), (4, NULL), (5, 50)").unwrap(); assert_eq!(count(&db, "SELECT * FROM t WHERE v BETWEEN 15 AND 35"), 2); assert_eq!(count(&db, "SELECT * FROM t WHERE v NOT BETWEEN 15 AND 35"), 2); assert_eq!(count(&db, "SELECT * FROM t WHERE id IN (1, 3, 9)"), 2); assert_eq!(count(&db, "SELECT * FROM t WHERE v IN (10, 50)"), 2); assert_eq!(count(&db, "SELECT * FROM t WHERE v NOT IN (10, 50)"), 2); assert_eq!(count(&db, "SELECT * FROM t WHERE id BETWEEN 2 AND 4 AND v IS NOT NULL"), 2); assert!(execute(&db, "SELECT * FROM t WHERE id IN ()").is_err()); assert!(execute(&db, "SELECT * FROM t WHERE id NOT 3").is_err()); let many = vec!["1"; 257].join(", "); assert!(execute(&db, &format!("SELECT * FROM t WHERE id IN ({})", many)).is_err()); let _ = std::fs::remove_dir_all(&dir); }